sys_script_include.script:
var RenewalDecisionService = Class.create();
RenewalDecisionService.prototype = {

    initialize: function () {
        this.C = Constants.CHOICE;
        this.T = Constants.TABLE;
    },

    // Most specific active rule wins: product > business line > catch-all, then priority.
    findRule: function (policyGr) {
        var best = null, bestScore = -1;
        var r = new GlideRecord(this.T.RENEWAL_RULE);
        r.addQuery('active', true);
        r.orderBy('priority');
        r.query();
        while (r.next()) {
            var score = 0;
            if (r.getValue('product')) {
                if (r.getValue('product') !== policyGr.getValue('product')) continue;
                score += 4;
            }
            if (r.getValue('business_line')) {
                if (r.getValue('business_line') !== policyGr.getValue('business_line')) continue;
                score += 2;
            }
            if (score > bestScore) {
                best = this._copy(r);
                bestScore = score;
            }
        }
        return best;
    },

    // Evidence for an expiring term.
    metrics: function (termGr) {
        var termId = termGr.getUniqueValue();
        var premium = parseFloat(termGr.getValue('written_premium')) || 0;
        var incurred = 0, claims = 0, mtas = 0;
        var cl = new GlideAggregate(this.T.CLAIM);
        cl.addQuery('policy_term', termId);
        cl.addAggregate('COUNT');
        cl.addAggregate('SUM', 'incurred_amount');
        cl.query();
        if (cl.next()) {
            claims = parseInt(cl.getAggregate('COUNT'), 10) || 0;
            incurred = parseFloat(cl.getAggregate('SUM', 'incurred_amount')) || 0;
        }
        var tx = new GlideAggregate(this.T.POLICY_TRANSACTION);
        tx.addQuery('policy_term', termId);
        tx.addQuery('type', this.C.TRANSACTION_TYPE.ENDORSEMENT);
        tx.addAggregate('COUNT');
        tx.query();
        if (tx.next())
            mtas = parseInt(tx.getAggregate('COUNT'), 10) || 0;
        return {
            written_premium: premium,
            incurred: incurred,
            loss_ratio: premium > 0 ? Math.round(incurred / premium * 10000) / 100 : 0,
            claim_count: claims,
            mta_count: mtas
        };
    },

    // Returns { decision, rule, metrics, reasons[] }. rateChangePct is optional input
    // (requested change from the broker / rating), compared to max_rate_change_pct.
    evaluate: function (termId, rateChangePct) {
        var term = new GlideRecord(this.T.POLICY_TERM);
        if (!term.get(termId))
            throw new Error('[RenewalDecisionService] policy_term not found: ' + termId);
        var policy = new GlideRecord(this.T.POLICY);
        policy.get(term.getValue('policy'));
        var rule = this.findRule(policy);
        var m = this.metrics(term);
        m.rate_change_pct = parseFloat(rateChangePct) || 0;
        if (!rule)
            return { decision: this.C.SYSTEM_DECISION.FULL_RE_UNDERWRITING, rule: null, metrics: m, reasons: ['no renewal rule matches - full re-underwriting by default'] };

        var reasons = [];
        this._check(reasons, rule.max_loss_ratio, m.loss_ratio, 'loss ratio ' + m.loss_ratio + '% > ' + rule.max_loss_ratio + '%');
        this._check(reasons, rule.max_claim_count, m.claim_count, m.claim_count + ' claims > ' + rule.max_claim_count);
        this._check(reasons, rule.max_mta_count, m.mta_count, m.mta_count + ' MTAs > ' + rule.max_mta_count);
        this._check(reasons, rule.max_rate_change_pct, Math.abs(m.rate_change_pct), 'rate change ' + m.rate_change_pct + '% beyond ' + rule.max_rate_change_pct + '%');
        if (rule.min_premium !== '' && m.written_premium < parseFloat(rule.min_premium))
            reasons.push('premium below ' + rule.min_premium);
        if (rule.max_premium !== '' && m.written_premium > parseFloat(rule.max_premium))
            reasons.push('premium above ' + rule.max_premium);
        return {
            decision: reasons.length ? rule.decision_otherwise : rule.decision_when_met,
            rule: rule.sys_id,
            metrics: m,
            reasons: reasons.length ? reasons : ['all criteria of "' + rule.name + '" met']
        };
    },

    // Fills a renewal_case from its policy's expiring term and stamps the system decision.
    applyToRenewalCase: function (renewalCaseId) {
        var rc = new GlideRecord(this.T.RENEWAL_CASE);
        if (!rc.get(renewalCaseId) || !rc.getValue('policy_term'))
            return null;
        var res = this.evaluate(rc.getValue('policy_term'), rc.getValue('rate_change_pct'));
        rc.setValue('renewal_rule', res.rule || '');
        rc.setValue('loss_ratio', res.metrics.loss_ratio);
        rc.setValue('claim_count', res.metrics.claim_count);
        rc.setValue('mta_count', res.metrics.mta_count);
        rc.setValue('system_decision', res.decision);
        rc.update();
        return res;
    },

    _check: function (reasons, limit, actual, msg) {
        if (limit === '' || limit === null || limit === undefined)
            return;
        if (actual > parseFloat(limit))
            reasons.push(msg);
    },

    _copy: function (r) {
        var o = { sys_id: r.getUniqueValue() };
        var f = ['name', 'max_loss_ratio', 'max_claim_count', 'max_mta_count', 'max_rate_change_pct', 'material_change_pct',
            'min_premium', 'max_premium', 'decision_when_met', 'decision_otherwise', 'lead_time_days', 'notification_days'];
        for (var i = 0; i < f.length; i++)
            o[f[i]] = r.getValue(f[i]) === null ? '' : String(r.getValue(f[i]));
        return o;
    },

    type: 'RenewalDecisionService'
};
